# Normalize the substitute argument: FALSE means real profanity, TRUE is
# an alias for "tame", and "tame"/"weird" select a substitution set.
normalize_substitute <- function(substitute) {
  if (is.logical(substitute) && length(substitute) == 1 && !is.na(substitute)) {
    return(if (substitute) "tame" else "off")
  }
  if (is.character(substitute) && length(substitute) == 1) {
    return(match.arg(substitute, c("tame", "weird")))
  }
  cli::cli_abort(
    "{.arg substitute} must be `TRUE`, `FALSE`, \"tame\", or \"weird\"."
  )
}

